const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.book}</svg>`;
const btn = (action, text, cls = 'btn', extra = '') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const levels = ['未开始', '学习中', '已学过', '已掌握'];

let storageError='',state;
try{state=loadRecords(localStorage).state;}catch(e){state=createState();storageError='新版记录损坏或不可读。原始数据未覆盖，请导出原始记录或导入有效的 v4 备份。';}
