let draft=state.draft?{candidate:{...state,tasks:state.draft.tasks,adjustments:state.draft.adjustments},start:state.draft.week,end:addDays(state.draft.week,6)}:null;
let guideState=createState(),onboardingSettings={...guideState.settings},onboardingStep='subjects';
let modal=null,modalStack=[],returnFocus=null,toastTimeout,lastDate=today(),undoIds=[];
